exercises.fix_solution:
def build_vocab(train_texts):
    words = sorted({word for text in train_texts for word in text.lower().split()})
    vocab = {word: i for i, word in enumerate(words, start=2)}
    vocab["<pad>"] = 0
    vocab["<unk>"] = 1
    return vocab
